suggest improvements for my java code:

class randomizedset {
    map<integer, integer> valuetoindex;
    list<integer> valuelist;
    random rand;

    public randomizedset() {
        valuetoindex = new hashmap<>();
        valuelist = new arraylist<>();
        rand = new random();
    }

    public boolean insert(int val) {
        if (valuetoindex.containskey(val)) {
            return false;
        } else {
            valuetoindex.put(val, valuelist.size());
            valuelist.add(val);
            return true;
        }
    }

    public boolean remove(int val) {
        if (!valuetoindex.containskey(val)) {
            return false;
        } else {
            int postoremove = valuetoindex.get(val);
            int valtomove = valuelist.get(valuelist.size() - 1);
            valuelist.set(postoremove, valtomove);
            valuelist.remove(valuelist.size() - 1);
            valuetoindex.put(valtomove, postoremove);
            valuetoindex.remove(val);
            return true;
        }
    }

    public int getrandom() {
        int pos = rand.nextint(valuelist.size());
        return valuelist.get(pos);
    }
}

