Here is a Java microservice using Spring Boot Reactive and MongoDB:

```java
@SpringBootApplication
public class CustomerServiceApplication {

	public static void main(String[] args) {
		SpringApplication.run(CustomerServiceApplication.class, args);
	}
}

@Repository
public interface CustomerRepository extends ReactiveMongoRepository<Customer, String> {
}

@Entity
public class Customer {
    @Id
    private String id;
    private String name;
    private int age;

    // Getters and setters
}

@RestController
public class CustomerController {
    @Autowired
    private CustomerRepository repository;

    @GetMapping("/customers")
    public Flux<Customer> getAllCustomers() {
        return repository.findAll();
    }

    @GetMapping("/customers/{id}")
    public Mono<Customer> getCustomerById(@PathVariable String id) {
        return repository.findById(id);
    }

    @PostMapping("/customers")
    public Mono<Customer> saveCustomer(@RequestBody Customer customer) {
        return repository.save(customer);
    }
}
```

- The Customer entity has an auto-generated id, name and age
- The CustomerRepository interface extends ReactiveMongoRepository to access MongoDB 
- The CustomerController has endpoints to get all customers, get by id, and save a new customer
- It returns Flux/Mono reactive types from the endpoints
- Spring Data MongoDB will generate the id automatically

This service can be deployed as a Spring Boot microservice and will connect to MongoDB to store and retrieve customer data. Let me know if you have any other questions!

Here's a basic Mail Transfer Agent in Swift that connects directly to the SMTP server of the recipient:

```swift
import Foundation

struct SMTPConnection {
    let host: String
    let port: Int
    var socket: TCPClientSocket?

    func connect() throws {
        socket = try TCPClientSocket(host: host, port: port)
    }

    func send(email: String, password: String, from: String, to: String, message: String) throws {
        try connect()

        let command = "EHLO localhost\r\n"
        try socket?.write(string: command)
        let response = try socket?.read()

        command = "AUTH LOGIN\r\n"
        try socket?.write(string: command)
        response = try socket?.read()

        let authUser = Data(email.utf8).base64EncodedString()
        command = authUser + "\r\n"
        try socket?.write(string: command)
        response = try socket?.read()

        let authPass = Data(password.utf8).base64EncodedString()
        command = authPass + "\r\n"
        try socket?.write(string: command)
        response = try socket?.read()

        command = "MAIL FROM: <\(from)>\r\n"
        try socket?.write(string: command)
        response = try socket?.read()

        command = "RCPT TO: <\(to)>\r\n"
        try socket?.write(string: command)
        response = try socket?.read()

        command = "DATA\r\n"
        try socket?.write(string: command)
        response = try socket?.read()

        message = message.replacingOccurrences(of: "\r\n", with: "\r\n ")
        command = message + "\r\n.\r\n"
        try socket?.write(string: command)
        response = try socket?.read()

        command = "QUIT\r\n"
        try socket?.write(string: command)
        response = try socket?.read()
    }
}

let smtp = SMTPConnection(host: "smtp.example.com", port: 587)
try smtp.send(email: "user@example.com", password: "password", 
              from: "user@example.com", to: "receiver@example.com", 
              message: "Hello from Swift!")
```

This code:

- Defines an SMTPConnection struct to handle the SMTP connection
- Implements a connect() method to connect to the SMTP server 
- Implements a send() method to authenticate, set the from/to addresses and send the email message
- Creates an SMTPConnection and sends a test email

