Here is how to use the pmtiles npm package to get features from coordinates:

```js
const pmtiles = require('pmtiles');

async function getFeaturesFromCoordinates(lon, lat) {
  // Load pmtiles data using pmtiles package
  const tiles = await pmtiles.load('pmtiles://example.com/data.pmtiles');

  const tileZoom = 14;

  const x = Math.floor(lon/360 + 0.5) * Math.pow(2, tileZoom); 
  const y = Math.floor((1 - Math.log(Math.tan(lat * Math.PI/180) + 1 / Math.cos(lat * Math.PI/180))/Math.PI) / 2 * Math.pow(2, tileZoom));

  const tile = tiles.getTile(y, x);

  return tile.features;
}

// Usage
const lon = -73.5;
