Here is a C++ program that converts a variant<X, Y> to variant<X, Y, Z>:

#include <variant>

using namespace std;

template <typename X, typename Y, typename Z>
variant<X, Y, Z> convert_variant(variant<X, Y> v) {
  return visit([](auto&& arg) -> variant<X, Y, Z> {
    if constexpr (is_same_v<decltype(arg), X>) {
      return variant<X, Y, Z>{forward<X>(arg)};
    } else if constexpr (is_same_v<decltype(arg), Y>) {
      return variant<X, Y, Z>{forward<Y>(arg)};
    } else {
      return variant<X, Y, Z>{Z{}};
    }
  }, v);
}

int main() {
  variant<int, string> v = 5;

  auto v2 = convert_variant<int, string, double>(v);

  return 0;
}

The key points:

- Use visit to examine the stored type of the input variant v
- Conditionally return a variant<X,Y,Z> containing the same value, wrapped in the appropriate type 
- Or return a default constructed Z if the input type doesn't match X or Y

This allows converting a variant to one with an additional alternative type added without modifying the existing value.

