            consoleText = GUI.TextField(new Rect(leftPos + 10f, textFieldTopPos, windowWidth - 20f, textFieldHeight), consoleText);

            GUI.Label(new Rect(leftPos + 10f, topPos + 5f, windowWidth - 20f, windowHeight - 30f), commandOutput);

            if (Event.current.isKey && Event.current.keyCode == KeyCode.Return)
            {
                if(consoleText == "heal")
                {
                    Heal();
                }
                else if (consoleText == "list")
                {
                    ListCommands();
                }

                consoleText = "";
            }
        }
    }

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.BackQuote))
        {
            showConsole = !showConsole;
            consoleText = "";
            commandOutput = "";
        }
    }

    private void Heal()
    {
        playerVitals.currentHealth += 100;
    }

    private void ListCommands()
    {
        StringBuilder sb = new StringBuilder();
        foreach(string command in commands)
        {
            sb.AppendLine(command);
        }
        commandOutput = sb.ToString();
    }
}
```

Please remember to assign the `playerVitals` variable in your script to reference the `PlayerVitals` component of your player.

This script will display a console window in the center of the screen when the backquote key is pressed. You can type commands into the text field at the bottom of the console window. When you press Enter, it will execute the command. If you type "heal" it will add 100 to `playerVitals.currentHealth`, and if you type "list" it will display a list of available commands in the console window.

