```javascript
<template>
  <div class="image-cropper">
    <input type="file" accept="image/*" @change="onFileSelect">
    <div class="crop-area">
      <canvas ref="cropCanvas" width="300" height="300"></canvas>
    </div>
    <button @click="cropImage">Crop</button>
    <div class="preview-area">
      <img ref="previewImage" />
    </div>
  </div>
</template>

<script>
import { ref } from 'vue';

export default {
  setup() {
    const cropCanvas = ref();
    const previewImage = ref();

    const onFileSelect = (e) => {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = () => {
        const image = new Image();
        image.onload = () => {
          cropCanvas.value.getContext('2d').drawImage(image, 0, 0);
        };
        image.src = reader.result;
      };
      reader.readAsDataURL(file);
    };

    const cropImage = () => {
      const context = cropCanvas.value.getContext('2d');
      const imageData = context.getImageData(0, 0, cropCanvas.value.width, cropCanvas.value.height);
      const croppedImageData = context.createImageData(300, 300);
      for (let i = 0; i < imageData.data.length; i += 4) {
        if (imageData.data[i + 3] > 0) {
          croppedImageData.data[i] = imageData.data[i];
          croppedImageData.data[i + 1] = imageData.data[i + 1];
          croppedImageData.data[i + 2] = imageData.data[i + 2];
          croppedImageData.data[i + 3] = imageData.data[i + 3];
        }
      }
      context.putImageData(croppedImageData, 0, 0);
      previewImage.value.src = cropCanvas.value.toDataURL();
    };

    return {
      cropCanvas,
      previewImage,
      onFileSelect,
      cropImage,
    };
  },
};
</script>

<style>
.image-cropper {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.crop-area {
  position: relative;
  width: 300px;
  height: 300px;
  border: 1px solid black;
}

.preview-area {
  width: 300px;
  height: 300px;
  border: 1px solid black;
}

img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
</style>
```

```delphi
program ShaderToy;

uses
  GLSLProgram,
  OpenGL,
  SysUtils;

var
  Program: TGLSLProgram;
  VertexShaderSource: string;
  FragmentShaderSource: string;
  Window: TGLWindow;

procedure LoadShaders;
begin
  VertexShaderSource :=
    '// Vertex shader' + #13#10 +
    'in vec2 position;' + #13#10 +
    'void main() {' + #13#10 +
    '  gl_Position = vec4(position, 0.0, 1.0);' + #13#10 +
    '}';

  FragmentShaderSource :=
    '// Fragment shader' + #13#10 +
    'uniform vec2 iResolution;' + #13#10 +
    'uniform float iTime;' + #13#10 +
    'in vec2 texCoord;' + #13#10 +
    'out vec4 FragColor;' + #13#10 +
    'void main() {' + #13#10 +
    '  vec2 uv = texCoord.xy * iResolution.xy;' + #13#10 +
    '  FragColor = vec4(uv.x, uv.y, 0.0, 1.0);' + #13#10 +
    '}';

  Program := TGLSLProgram.Create(VertexShaderSource, FragmentShaderSource);
end;

procedure Initialize;
begin
  Window := TGLWindow.Create;
  Window.Caption := 'ShaderToy';
  Window.Width := 640;
  Window.Height := 480;
  Window.Show;

  LoadShaders;
end;

procedure Render;
begin
  glClearColor(0.0, 0.0, 0.0, 1.0);
  glClear(GL_COLOR_BUFFER_BIT);

  glUseProgram(Program.Handle);

  glUniform2fv(glGetUniformLocation(Program.Handle, 'iResolution'), 1, [Window.Width, Window.Height]);
  glUniform1f(glGetUniformLocation(Program.Handle, 'iTime'), GetTickCount / 1000.0);

  glBegin(GL_TRIANGLES);
  glVertexAttrib2f(0, -1.0, -1.0);
  glVertexAttrib2f(0,  1.0, -1.0);
  glVertexAttrib2f(0,  0.0,  1.0);
  glEnd;

  glUseProgram(0);
end;

procedure Main;
begin
  Initialize;
  while not Window.Done do
  begin
    if Window.HandleCreated then
    begin
      Render;
      Window.SwapBuffers;
    end;
    Window.ProcessMessages;
  end;
end;

begin
  Main;
end.
```

